def histogram(test):
    # Split the input string into individual characters
    letters = test.split()

    # If no letters, return empty dictionary
    if not letters:
        return {}

    # Count occurrences of each letter
    counts = {letter: letters.count(letter) for letter in letters}

    # Find the maximum count
    max_count = max(counts.values())

    # Return only letters with the maximum count
    return {letter: count for letter, count in counts.items() if count == max_count}

# Test cases
print(histogram('a b c'))          # Expected: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))        # Expected: {'a': 2, 'b': 2}
print(histogram('a b c a b'))      # Expected: {'a': 2, 'b': 2}
print(histogram('b b b b a'))      # Expected: {'b': 4}
print(histogram(''))               # Expected: {}
```

