def even_odd_count(num):
    even = 0
    odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

if __name__ == "__main__":
    print(even_odd_count(-12))  # Expected: (1, 1)
    print(even_odd_count(123))  # Expected: (1, 2)
